"""Deterministic static Pages build: no external assets, keys or backend."""
import csv
import html
import io
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
D = json.loads((ROOT/'data/research.json').read_text())
def e(value): return html.escape(str(value), quote=True)
S = {s['id']:s for s in D['sources']}
NAV = [('overview','Overview','01'),('strategies','Strategy lab','02'),('markets','Line origination','03'),('correlations','Correlations','04'),('validation','Validation gates','05'),('leaderboard','Leaderboard','06'),('sources','Sources & findings','07'),('review','Flagged for Review','08')]
def refs(ids): return '<span class="refs">' + ''.join(f'<a href="{e(S[i]["url"])}" target="_blank" rel="noopener noreferrer" title="{e(S[i]["title"])}">{e(i)} ↗</a>' for i in ids) + '</span>'
def badge(v): return f'<span class="badge {"ok" if v in ("Checked","Definition checked") else "warn" if "review" in v.lower() or "Unverified" in v or "Blocked" in v else "neutral"}">{e(v)}</span>'
def cell(v):
    if v is None: return '<td class="missing" aria-label="Unverified: value unavailable"></td>'
    return '<td>'+str(v)+'</td>'
def table(title,desc,headers,rows,id='records',filters=None):
    controls=f'<label class="search"><span aria-hidden="true">⌕</span><input type="search" data-search="{id}" aria-label="Search {e(title)}" placeholder="Search this table…"></label>'
    if filters:
        controls+=f'<label class="filter">Category <select data-filter="{id}"><option value="">All categories</option>'+''.join(f'<option>{e(f)}</option>' for f in filters)+'</select></label>'
    return f'''<section class="panel table-panel"><div class="panel-head"><div><h2>{title}</h2><p>{desc}</p></div><button class="export" data-export="{id}">Export CSV <span aria-hidden="true">↓</span></button></div><div class="table-tools">{controls}<span class="row-count" data-count="{id}">{len(rows)} entries</span></div><div class="table-wrap"><table id="{id}"><caption class="sr-only">{title}. Blank numeric cells are unverified, not zero. Source links on policy rows are methodological references.</caption><thead><tr>{''.join('<th scope="col">'+h+'</th>' for h in headers)}</tr></thead><tbody>{''.join('<tr>'+''.join(cell(c) for c in row)+'</tr>' for row in rows)}</tbody></table></div><p class="empty" hidden>No matching entries. Try another search or category.</p></section>'''
def note(title,text): return f'<aside class="notice"><span class="notice-icon" aria-hidden="true">i</span><div><strong>{title}</strong><p>{text}</p></div></aside>'
def strategy_table(compact=False):
    rows=[]
    for x in D['strategies']:
        name=f'<span class="record-id">{x["id"]}</span><strong>{e(x["name"])}</strong>'
        if compact: rows.append([name,e(x['market']),badge(x['status']),f'<span class="gate-dots" aria-label="0 of 7 gates passed">○ ○ ○ ○ ○ ○ ○</span><small>0 / 7 gates</small>',refs(x['sources'])])
        else: rows.append([name,e(x['market']),e(x['signal'])+'<small>'+e(x['model'])+'</small>',e(x['risk']),badge(x['status']),refs(x['sources'])])
    return table('Research queue' if compact else 'Candidate strategies','Hypotheses to test. No candidate has demonstrated an edge.', ['Strategy','Market','Status','Validation','Primary references'] if compact else ['Strategy','Market','Proposed signal & model','Failure modes','Status','Primary references'],rows,'strategies',['Single','Player prop','Parlay','Prop combo'])
def overview():
    return f'''<section class="hero"><div class="hero-copy"><span class="eyebrow">NFL RESEARCH / EVIDENCE FIRST</span><h2>Find the signal.<br><span>Challenge the edge.</span></h2><p>A transparent research desk for originating NFL lines, testing strategies and separating evidence from noise.</p><a class="primary" href="pages/strategies.html">Explore strategy lab <span>↗</span></a><a class="text-link" href="research/EXECUTIVE_SUMMARY.md">Read executive summary →</a></div><div class="field-art" aria-hidden="true"><div class="field-top">OWN5 · RESEARCH FIELD</div><div class="field-grid"><span>10</span><span>20</span><span>30</span><span>40</span><span>50</span></div><svg viewBox="0 0 300 140"><path d="M20 115 L80 115 L130 65 L205 65 L260 15"/><circle cx="20" cy="115" r="5"/><circle cx="130" cy="65" r="5"/><circle cx="260" cy="15" r="5"/></svg><div class="field-bottom">HYPOTHESIS → VALIDATION → REPLICATION</div></div></section>
<div class="stats"><article><span>Research candidates</span><strong>{len(D['strategies']):02}</strong><small>Across four market categories</small></article><article><span>Validated strategies</span><strong>00<em> / {len(D['strategies']):02}</em></strong><small>No empirical gates run</small></article><article><span>Primary sources checked</span><strong>{len(D['sources']):02}</strong><small>NFL, operator & methodology</small></article><article><span>Open review items</span><strong class="amber">{len(D['flags']):02}</strong><a href="pages/review.html">View evidence gaps ↗</a></article></div>
{note('Research mode. Not a betting feed.','No historical odds dataset or matched outcome sample has been acquired. Fair lines, returns and correlations are blank—not estimated. No bets or cash rewards are active.')}
<div class="section-title"><h2>Executive brief</h2><span class="eyebrow">AS OF {D['as_of']}</span></div>
<div class="brief-grid"><article class="panel brief"><span class="step">01 / THE OBJECTIVE</span><h3>Originate, don’t imitate.</h3><p>Develop score and player-outcome distributions, turn them into fair prices, then compare with an exact timestamped quote. Current models are specifications, not fitted forecasts.</p><a href="pages/markets.html">Pricing framework →</a></article><article class="panel brief"><span class="step">02 / THE STANDARD</span><h3>Evidence over a hot streak.</h3><p>Seven gates cover provenance, leakage, holdouts, calibration, dependence, skill evidence and prospective replication. Luck cannot be eliminated; uncertainty must be measured.</p><a href="pages/validation.html">Validation policy →</a></article><article class="panel brief"><span class="step">03 / THE DECISION</span><h3>Abstain until qualified.</h3><p>All eight candidates are blocked by missing empirical data. Rankings and rewards stay blank. The leaderboard is a proposed paper-research competition, not a claim of profitability.</p><a href="pages/leaderboard.html">Competition rules →</a></article></div>
{strategy_table(True)}'''
def strategies(): return note('A research hypothesis is not a proven signal.','Signals below are project proposals. Source links establish feature definitions or methodology—not a predictive edge. All strategies must pass G01–G07.')+strategy_table()
def markets(): return note('No originated numerical lines yet.','A fitted, calibrated outcome distribution and exact settlement rules are required. The formulas are derived identities under stated assumptions, not observed market data.')+table('Fair-line framework','Project methods · empty prices mean unverified, not unavailable betting opportunities.',['Market','Required model output','Pricing method','Critical constraint','Model p','Fair decimal','References'],[[f'<span class="record-id">{x["id"]}</span><strong>{e(x["market"])}</strong>',e(x['output']),e(x['method']),e(x['caution']),None,None,refs(x['sources'])] for x in D['markets']],'markets')+note('Expected value & de-vig','For unit stakes without partial settlement: EV = p(win) × decimal odds + p(push) − 1. Proportional no-vig probabilities normalize inverse prices from a complete, synchronized, mutually exclusive no-push market. This is a convention, not ground truth. See the methodology for derivations and limitations.')
def correlations(): return note('No coefficient is inferred.','The sample size, coefficient, interval and joint win probability remain blank until matched observations are obtained. Pairwise correlation alone cannot price a multi-leg bet; zero Pearson correlation does not prove independence.')+table('Dependence research map','Planned estimands · game/week-block uncertainty · frozen thresholds for binary leg outcomes.',['Pair / exposure','Observation unit','Proposed controls','Pearson r','95% interval','Paired n','Joint win p','Status','References'],[[f'<span class="record-id">{x["id"]}</span><strong>{e(x["pair"])}</strong>',e(x['unit']),e(x['controls']),None,None,None,None,badge(x['status']),refs(x['sources'])] for x in D['correlations']],'correlations')+note('Estimation protocol','Match by event and player identifiers; log missingness and independent cluster count. Compare raw and pregame-adjusted associations, assess role/window stability, bootstrap shared game/week blocks, and validate the full joint model out of sample. Do not substitute a narrative for a number.')
def validation(): return note('Mandatory, proposed project policy—not an NFL standard.','All seven gates apply before eligibility; G05 is additional joint-pricing evidence for parlays and combos. No empirical gate has been run. Numeric thresholds are design choices, not guarantees of skill.')+table('Validation gates','Sequential fail-closed workflow · no evidence means abstain.',['Gate','Pass requirement · project policy','Applies to','Current status','Methodology reference'],[[f'<span class="record-id">{x["id"]}</span><strong>{e(x["name"])}</strong>',e(x['rule']),e(x['applies']),badge(x['status']),refs(x['sources'])] for x in D['gates']],'gates')+note('What is actually implemented?','The repository includes input-checked pricing, Pearson, Brier, Holm correction and fail-closed gate-declaration utilities with unit tests. It does not include a fitted forecasting model, a historical data importer, or an automated empirical gate auditor.')
def leaderboard():
    rows=[[None,f'<span class="record-id">{x["id"]}</span><strong>{e(x["name"])}</strong>',e(x['market']),None,None,None,None,badge('Not eligible'),refs(x['sources'])] for x in D['strategies']]
    return note('No qualified entries. No funded prizes.','Rows are the research registry in ID order, not rankings. Rank, samples, return bounds and reward values are blank. No sponsor, monetary prize or payout system has been verified.')+table('Strategy leaderboard','Eligibility requires all seven gates and a reproducible audit. No performance figures are available.',['Rank','Candidate','Division','Sample n','Net ROI','95% lower bound','Reward','Eligibility','References'],rows,'leaderboard',['Single','Player prop','Parlay','Prop combo'])+table('Competition charter','Proposed project governance · references support statistical methods, not independent contest approval.',['ID','Policy area','Proposed rule','References'],[[x['id'],e(x['topic']),e(x['rule']),refs(x['sources'])] for x in D['competition']],'charter')
def sources(): return note('Verified definitions, not verified profitability.','Checked means the specific finding below was read in the primary publisher’s page on 2026-11-02. It is not a full-site audit, an immutable feed, or an endorsement of a proposed strategy. Numeric player statistics were excluded when extraction omitted headers.')+table('Official feature & settlement definitions','Each statement is scoped to its linked primary source. No current player statistics are claimed.',['ID','Definition','Checked finding','Scope','Status','Official source'],[[x['id'],f'<strong>{e(x["metric"])}</strong>',e(x['definition']),e(x['scope']),badge(x['status']),refs(x['sources'])] for x in D['facts']],'facts')+table('Primary-source register','Reviewed 2026-11-02 · official NFL/operator publishers and official statistical-project documentation.',['ID / publisher','Document','Specific finding checked','Limitations','Check date','Source'],[[f'<strong>{x["id"]}</strong><small>{e(x["publisher"])}</small>',e(x['title']),e(x['finding']),e(x['limitation']),x['checked'],refs([x['id']])] for x in D['sources']],'sources')
def review(): return note('Published openly. Nonblocking for the research site.','These items block empirical validation or live betting claims, not publication of the dashboard. No manual input is needed to browse; no missing value has been filled in. Research limitations are not silently marked complete.')+table('Flagged for Review','Evidence gaps and irregularities · retained for manual source review.',['ID / severity','Issue','Finding / limitation','Affected scope','Status','Primary reference'],[[f'<span class="record-id">{x["id"]}</span>'+badge(x['severity']),f'<strong>{e(x["issue"])}</strong>',e(x['detail']),e(x['scope']),badge(x['status']),refs(x['sources'])] for x in D['flags']],'review',['High','Medium','Low'])
CONTENT = dict(overview=overview,strategies=strategies,markets=markets,correlations=correlations,validation=validation,leaderboard=leaderboard,sources=sources,review=review)
SUBTITLES = dict(overview='Your evidence-first NFL research desk.',strategies='Eight hypotheses. One consistent evidence standard.',markets='From outcome distributions to fair market prices.',correlations='Measure dependence. Never assume independence.',validation='A good story is not a passing result.',leaderboard='Reward reproducibility, not a lucky run.',sources='Every finding has a scope and a source.',review='Unknowns, limitations and irregularities—in the open.')
for key,title,num in NAV:
    prefix='' if key=='overview' else '../'
    def link(k): return prefix+('index.html' if k=='overview' else f'pages/{k}.html')
    content=CONTENT[key]()
    if prefix:
        content=content.replace('href="pages/','href="').replace('href="research/','href="../research/')
    body=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="Evidence-first NFL line origination research. Sourced definitions, proposed strategies and transparent validation gaps."><meta name="theme-color" content="#173e36"><title>{e(title)} · OWN5 NFL Research</title><link rel="icon" href="{prefix}assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="{prefix}assets/style.css"><script src="{prefix}assets/app.js" defer></script></head><body><a class="skip" href="#main">Skip to content</a><div class="layout"><aside class="sidebar"><a class="brand" href="{link('overview')}"><span class="brand-icon">O<span>5</span></span><span>OWN5<small>NFL RESEARCH DESK</small></span></a><div class="workspace"><span class="live-dot"></span> Research workspace <span class="workspace-arrow">⌄</span></div><span class="nav-caption">WORKSPACE</span><nav aria-label="Main navigation">{''.join(f'<a href="{link(k)}" class="nav-item {"active" if k==key else ""}" '+('aria-current="page"' if k==key else '')+f'><span class="nav-number">{n}</span>{t}'+('<span class="nav-tag">10</span>' if k=='review' else '')+'</a>' for k,t,n in NAV)}</nav><div class="side-bottom"><div class="mode"><span class="live-dot"></span> Paper research only</div><p>No bets. No fabricated results.<br>Evidence before exposure.</p><a href="https://github.com/sassnarep3-star/Own5" target="_blank" rel="noopener noreferrer">View repository ↗</a></div></aside><div class="main-shell"><header class="topbar"><div><span class="breadcrumb">Workspace <span>/</span> {e(title)}</span></div><div class="topbar-right"><span class="desktop-only">NFL / METHODOLOGY</span><span class="avatar">O5</span></div></header><main id="main"><div class="page-heading"><div><span class="eyebrow">RESEARCH WORKSPACE</span><h1>{e(title)}</h1><p>{SUBTITLES[key]}</p></div><span class="date-label"><span class="live-dot"></span> Reviewed {D['as_of']}</span></div>{content}<footer><span>OWN5 <span class="footer-divider">/</span> Independent NFL research · Not affiliated with the NFL.</span><span>Blank cells = unverified. <a href="{prefix}docs/index.html">NBA Line-Origination Lab ↗</a> · <a href="{prefix}data/research.json">Open dataset ↗</a> · <a href="{prefix}research/METHODOLOGY.md">Methodology ↗</a> · <a href="{prefix}research/VERIFICATION.md">Verification ↗</a></span></footer></main></div></div></body></html>'''
    path=ROOT/('index.html' if key=='overview' else f'pages/{key}.html')
    path.parent.mkdir(exist_ok=True)
    path.write_text(body+'\n')
print('Built 8 static, source-linked pages.')
